    try { currentProfile = { ...fallback, ...((await M.request(`user_profiles?select=display_name,email,phone,login_id,created_at&user_id=eq.${encodeURIComponent(access.user.id)}&limit=1`, { private: true }))?.[0] || {}) }; } catch (_) { /* Session identity remains sufficient for this self-account view. */ }
    const host = $('#currentAdminProfile');
