    try { const [counts, finance] = await Promise.all([dashboardCounts(scope.requestCount), dashboardFinance(scope.request)]); renderFinance(finance); renderOperations(counts); } catch (err) { if (err.code !== M.network.STALE_RESPONSE) $('#stats').innerHTML = M.ui.error('โหลดสรุปไม่สำเร็จ', err.message); return; }
    const stop = M.network.startBackgroundSync({ key: 'admin-dashboard-counts', intervalMs: 30_000, task: async () => { const freshRequest = (path, options) => scope.request(path, { ...options, forceFresh: true }); const [counts, finance] = await Promise.all([dashboardCounts((path, options) => scope.requestCount(path, { ...options, forceFresh: true })), dashboardFinance(freshRequest)]); const data = { counts, finance }; return { changed: JSON.stringify(counts) !== lastOperationalSignature || JSON.stringify(finance) !== lastFinancialSignature, data }; }, onData: result => { renderFinance(result.data.finance); renderOperations(result.data.counts); } });
    const originalStop = stop; addEventListener('pagehide', originalStop, { once: true });
