    const bind = () => { $('#addStore').onclick = () => openStoreForm(null); const search = host.querySelector('#storeSearch'); let searchTimer = 0; search.oninput = event => { const value = event.currentTarget.value; window.clearTimeout(searchTimer); searchTimer = window.setTimeout(() => { const next = host.querySelector('#storeSearch'); if (!next) return; next.value = value; render({ preserveFocus: true }); const restored = host.querySelector('#storeSearch'); if (restored) { restored.focus(); restored.setSelectionRange(value.length, value.length); } }, 120); }; host.querySelectorAll('[data-store-filter]').forEach(button => button.onclick = () => { host.dataset.filter = button.dataset.storeFilter; render(); }); host.querySelectorAll('[data-store-category]').forEach(button => button.onclick = () => { host.dataset.category = button.dataset.storeCategory; render(); }); host.querySelectorAll('[data-store-menu]').forEach(button => button.onclick = () => openStoreMenu(rows.find(row => row.id === button.dataset.storeMenu))); };
    const render = ({ preserveFocus = false } = {}) => { const searchBefore = host.querySelector('#storeSearch'), query = String(searchBefore?.value || '').trim().toLowerCase(), filter = host.dataset.filter || 'all', categoryFilter = host.dataset.category || 'all'; const filtered = rows.filter(row => { const match = !query || [row.name,row.owner_email,row.phone,row.category_id,row.id].some(value => String(value || '').toLowerCase().includes(query)); const type = filter === 'all' || (filter === 'open' && row.active !== false && !row.emergency_closed && !['suspended','archived'].includes(row.moderation_status)) || (filter === 'emergency' && row.emergency_closed) || (filter === 'suspended' && (row.active === false || ['suspended','archived'].includes(row.moderation_status))); const categoryMatch = categoryFilter === 'all' || String(row.category_id || 'ไม่ระบุหมวด') === categoryFilter; return match && type && categoryMatch; }); const grouped = filtered.reduce((map, row) => { const key = String(row.category_id || 'ไม่ระบุหมวด').trim() || 'ไม่ระบุหมวด'; (map[key] ||= []).push(row); return map; }, {}); const sections = Object.entries(grouped).sort(([a],[b]) => a.localeCompare(b, 'th')).map(([category, items]) => { const cards = items.map(row => ['<article class="admin-store-row"><button class="admin-store-identity" data-store-section="menu" data-store-menu="', h(row.id), '" aria-label="เปิดเมนูจัดการ ', h(row.name || ''), '"><span class="admin-store-symbol">', row.image_url ? '<img src="' + h(row.image_url) + '" alt="โลโก้ร้าน">' : h(row.emoji || '🍽️'), '</span><span><strong>', h(row.name || 'ร้านไม่มีชื่อ'), '</strong><small>', h(row.owner_email || '-'), ' · ', h(row.eta || 'ไม่ระบุเวลาจัดส่ง'), '</small></span></button><div class="admin-store-row-meta"><span class="admin-state ', stateClass(row), '">', h(storeState(row)), '</span><small>GP ', Number(row.settlement_gp_percent || 0).toLocaleString('th-TH'), '%</small></div><button class="mpa-button mpa-button-secondary admin-store-open-menu" data-store-menu="', h(row.id), '">จัดการ</button></article>'].join('')).join(''); return '<section class="admin-store-group"><div class="admin-store-group-head"><div><h2>' + h(category) + '</h2><span class="mpa-muted">' + items.length + ' ร้านในหมวดนี้</span></div></div><div class="admin-store-list">' + cards + '</div></section>'; }).join(''); const categoryButtons = [...new Set(rows.map(row => String(row.category_id || 'ไม่ระบุหมวด')))].sort((a,b) => a.localeCompare(b, 'th')).map(category => '<button class="mpa-button ' + (categoryFilter === category ? '' : 'mpa-button-secondary') + '" data-store-category="' + h(category) + '">' + h(category) + ' (' + rows.filter(row => String(row.category_id || 'ไม่ระบุหมวด') === category).length + ')</button>').join(''); host.innerHTML = '<div class="admin-store-toolbar"><label class="mpa-field"><span>ค้นหาร้านค้า</span><input id="storeSearch" type="search" placeholder="ชื่อร้าน อีเมลติดต่อ เบอร์โทร หรือรหัสร้าน" value="' + h(query) + '"></label><div class="admin-filter-row" aria-label="กรองสถานะร้าน"><button class="mpa-button ' + (filter === 'all' ? '' : 'mpa-button-secondary') + '" data-store-filter="all">ทั้งหมด (' + rows.length + ')</button><button class="mpa-button ' + (filter === 'open' ? '' : 'mpa-button-secondary') + '" data-store-filter="open">เปิดรับงาน</button><button class="mpa-button ' + (filter === 'emergency' ? '' : 'mpa-button-secondary') + '" data-store-filter="emergency">ปิดร้านฉุกเฉิน</button><button class="mpa-button ' + (filter === 'suspended' ? '' : 'mpa-button-secondary') + '" data-store-filter="suspended">ระงับ/ปิด</button></div><div class="admin-filter-row admin-store-category-filters" aria-label="กรองประเภทร้าน"><span class="admin-filter-label">ประเภทร้าน</span><button class="mpa-button ' + (categoryFilter === 'all' ? '' : 'mpa-button-secondary') + '" data-store-category="all">ร้านทั้งหมด (' + rows.length + ')</button>' + categoryButtons + '</div></div>' + (sections || M.ui.empty('ไม่พบร้านค้าที่ตรงกับคำค้น สถานะ หรือประเภทร้านที่เลือก')); bind(); };
    const load = async () => { try { rows = await M.request('stores?select=id,owner_id,name,emoji,description,rating,eta,location,active,created_at,updated_at,owner_email,contact_email,image_url,open_time,close_time,order_cutoff_minutes,emergency_closed,emergency_note,emergency_closed_at,category_id,background_url,settlement_gp_percent,phone,moderation_status,moderation_reason,moderation_changed_at,moderation_changed_by&order=name.asc&limit=1000', { private: true }); render(); } catch (error) { host.innerHTML = M.ui.error('โหลดร้านค้าไม่สำเร็จ', error.message); } }; load();
