    const inventoryCallout = feature === 'inventory' ? '<section class="mpa-card" style="box-shadow:none;margin-bottom:16px;background:#f5fbff;border-color:#c9dff8"><strong>หน้านี้เป็นรายงานอ่านอย่างเดียว</strong><p class="mpa-muted">ใช้สำหรับตรวจภาพรวมเท่านั้น หากต้องการแก้ไขราคา สต็อก หรือสถานะสินค้า ให้เปิด Admin Retail ซึ่งเป็นจุดจัดการหลัก</p><a class="mpa-button" href="admin-retail.html">เปิด Admin Retail</a></section>' : '';
